// The webhook data is nested in body
const webhookData = $input.all()[0].json.body;

// Generate unique request ID
const requestId = `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Simple hash function (since crypto is blocked) (fingerprint)
function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return Math.abs(hash).toString(16).padStart(16, '0');
}

// Calculate email hash for duplicate detection
const hashInput = `${webhookData.from}|${webhookData.subject}|${webhookData.body}`;
const emailHash = simpleHash(hashInput);

return [{
  json: {
    request_id: requestId,
    email_hash: emailHash,
    from: webhookData.from,
    subject: webhookData.subject,
    body: webhookData.body,
    customer_id: webhookData.customer_id || null,
    timestamp_started: new Date().toISOString()
  }
}];

// === POLICY ENGINE ===
// Reads classification output, applies deterministic rules,
// output a routing decision.

// 1. Pull data from upstream nodes
// The fallback model runs only when the first call fails, so take whichever one answered.
function readClassifier(nodeName) {
  try {
    const j = $(nodeName).item.json;
    return j?.choices?.[0]?.message?.content ? j : null;
  } catch (e) {
    return null;
  }
}

const primary = readClassifier('Classify Email');
const llm = primary ?? readClassifier('Classify Email Fallback') ?? {};
const fallback_triggered = !primary && Boolean(llm.model);
const rawText = llm?.choices?.[0]?.message?.content ?? null;
const promptBuiltAt = $('Build Classification Prompt').item.json.timestamp_prompt_built;
const metadata = $('Generate Request Metadata').item.json;

// 2. Configuration (would normally live in env/config)
const CONFIDENCE_THRESHOLDS = {
  billing_issue: 0.75,
  technical_issue: 0.70,
  refund_request: 0.80,
  legal_escalation: 0.90,
  unknown: 1.01 // impossible threshold = always escalate
};

const CRITICAL_RISK_FLAGS = ['lawsuit', 'compliance', 'fraud'];
const VALID_RISK_FLAGS = ['refund', 'chargeback', 'lawsuit', 'compliance', 'fraud', 'outage', 'data_loss'];

const ROUTING_QUEUES = {
  billing_issue: 'billing_team_queue',
  technical_issue: 'support_tier1_queue',
  refund_request: 'billing_team_queue',
  legal_escalation: 'legal_team_queue',
  unknown: 'human_review_queue'
};

const COST_LIMIT_USD = 0.10;
const LATENCY_LIMIT_MS = 15000;

// Groq prices, USD per million tokens (console.groq.com, 2026-09-20)
const PRICES = {
  'openai/gpt-oss-20b': { input: 0.075, output: 0.30 },
  'openai/gpt-oss-120b': { input: 0.15, output: 0.60 },
};

// 3. Real cost and latency of the LLM call
// Latency: from the prompt being built to the reply arriving here.
const latency_ms = Date.now() - Date.parse(promptBuiltAt);
const prompt_tokens = llm?.usage?.prompt_tokens ?? 0;
const completion_tokens = llm?.usage?.completion_tokens ?? 0;
const price = PRICES[llm.model] ?? { input: 0, output: 0 };
const cost_usd = Math.round(prompt_tokens * price.input + completion_tokens * price.output) / 1e6;

// Details of the call, added to every result below so the later nodes read one place.
const llmInfo = {
  model_used: llm.model ?? 'none',
  fallback_triggered: fallback_triggered,
  prompt_tokens: prompt_tokens,
  completion_tokens: completion_tokens,
  total_tokens: llm?.usage?.total_tokens ?? 0,
  raw_output: rawText,
};

// 4. Initialize tracking
const policiesEvaluated = [];
const policiesPassed = [];
const policiesFailed = [];

// 5.  Policy checks (we'll fill these in)

// CHECK 0: LLM output validation
// Groq's strict schema mode should already enforce this shape. This check is the
// second guard: bad output escalates instead of crashing.
policiesEvaluated.push('output_validation_check');

const validationErrors = [];
let classification = null;
try {
  classification = JSON.parse(rawText ?? '');
} catch (e) {}

const c = classification;
const noModelAnswered = !llm.model;
if (noModelAnswered) {
  validationErrors.push('no model answered: the main model and the fallback both failed');
} else if (c === null || typeof c !== 'object' || Array.isArray(c)) {
  validationErrors.push('output is not a JSON object');
} else {
  if (!Object.hasOwn(CONFIDENCE_THRESHOLDS, c.intent)) validationErrors.push(`unknown intent: ${c.intent}`);
  if (typeof c.confidence !== 'number' || c.confidence < 0 || c.confidence > 1) validationErrors.push(`confidence is not a number from 0 to 1: ${c.confidence}`);
  if (typeof c.summary !== 'string' || c.summary.length > 500) validationErrors.push('summary is missing or longer than 500 characters');
  if (typeof c.reasoning !== 'string') validationErrors.push('reasoning is missing');
  if (!Array.isArray(c.risk_flags)) {
    validationErrors.push('risk_flags is not a list');
  } else {
    const unknownFlags = c.risk_flags.filter(flag => !VALID_RISK_FLAGS.includes(flag));
    if (unknownFlags.length > 0) validationErrors.push(`unknown risk flags: ${unknownFlags.join(', ')}`);
  }
}

if (validationErrors.length > 0) {
  policiesFailed.push('output_validation_check');
  return [{
    json: {
      request_id: metadata.request_id,
      ...llmInfo,
      decision: 'escalate',
      destination: 'human_review_queue',
      escalation_reason: noModelAnswered ? 'llm_unavailable' : 'invalid_llm_output',
      escalation_priority: 'high',
      validation_errors: validationErrors,
      policies_evaluated: policiesEvaluated,
      policies_passed: policiesPassed,
      policies_failed: policiesFailed,
      // Safe placeholder so the database writes still have valid values
      classification: {
        intent: 'unknown',
        confidence: 0,
        summary: '',
        risk_flags: [],
        reasoning: 'LLM output failed validation: ' + validationErrors.join('; ')
      },
      validation_success: false,
      cost_usd: cost_usd,
      latency_ms: latency_ms,
    }
  }];
} else {
  policiesPassed.push('output_validation_check');
}

// CHECK 1: Critical risk flags
// TODO
policiesEvaluated.push('risk_flag_check');

const found = classification.risk_flags.filter(flag => CRITICAL_RISK_FLAGS.includes(flag));

if (found.length > 0) {
  policiesFailed.push('risk_flag_check');
  return [{
    json: {
      request_id: metadata.request_id,
      ...llmInfo,
      decision: 'escalate',
      destination: 'human_review_queue',
      escalation_reason: 'critical_risk_flag',
      escalation_priority: 'critical',
      triggered_flags: found,
      policies_evaluated: policiesEvaluated,
      policies_passed: policiesPassed,
      policies_failed: policiesFailed,
      classification: classification,
    validation_success: true,
      cost_usd: cost_usd,
      latency_ms: latency_ms,
    }
  }];
} else {
  policiesPassed.push('risk_flag_check');
}

// CHECK 2: Budget
// TODO
policiesEvaluated.push('budget_check');

if (cost_usd > COST_LIMIT_USD || latency_ms > LATENCY_LIMIT_MS) {
  policiesFailed.push('budget_check');
  return [{
  json: {
    request_id: metadata.request_id,
    ...llmInfo,
    decision: 'escalate',
    destination: 'human_review_queue',
    escalation_reason: 'budget_exceeded',
    escalation_priority: 'high',
    cost_usd: cost_usd,
    latency_ms: latency_ms,
    policies_evaluated: policiesEvaluated,
    policies_passed: policiesPassed,
    policies_failed: policiesFailed,
    classification: classification,
    validation_success: true
  }
}];
} else {
  policiesPassed.push('budget_check');
}

// CHECK 3: Confidence
// TODO
policiesEvaluated.push('confidence_check');

const threshold = CONFIDENCE_THRESHOLDS[classification.intent];
if (threshold === undefined) {
  throw new Error(`No threshold defined for intent: ${classification.intent}`);
}
if (classification.confidence < threshold) {
  policiesFailed.push('confidence_check');
  const escalation_priority = classification.intent === 'legal_escalation' ? 'critical' : 'medium';
  return [{
  json: {
    request_id: metadata.request_id,
    ...llmInfo,
    decision: 'escalate',
    destination: 'human_review_queue',
    escalation_reason: 'low_confidence',
    escalation_priority: escalation_priority,
    confidence_threshold: threshold,
    actual_confidence: classification.confidence,
    policies_evaluated: policiesEvaluated,
    policies_passed: policiesPassed,
    policies_failed: policiesFailed,
    classification: classification,
    validation_success: true,
    cost_usd: cost_usd,
    latency_ms: latency_ms,
  }
}];
} else {
  policiesPassed.push('confidence_check');
}

// 6. Default: auto-route
return [{
  json: {
    request_id: metadata.request_id,
    ...llmInfo,
    decision: 'auto_route',
    destination: ROUTING_QUEUES[classification.intent],
    escalation_reason: null,
    escalation_priority: null,
    policies_evaluated: policiesEvaluated,
    policies_passed: policiesPassed,
    policies_failed: policiesFailed,
    classification: classification,
    validation_success: true,
    cost_usd: cost_usd,
    latency_ms: latency_ms,
  }
}];

