// === BUILD TRACE ===
// Puts together the route card for this request: each step, in order, with
// what happened there. Only steps with a recorded clock time get a time.

const meta = $('Generate Request Metadata').item.json;
const prompt = $('Build Classification Prompt').item.json;
const dup = $('Check Duplicate').item.json;
const policy = $('Policy Engine').item.json;
const finishedAt = new Date();

const steps = [
  { step: 1, name: 'receive', started_at: meta.timestamp_started,
    detail: { email_hash: meta.email_hash } },
  { step: 2, name: 'duplicate_check',
    detail: { is_duplicate: dup.is_duplicate } },
  { step: 3, name: 'store_request',
    detail: { status: 'processing' } },
  { step: 4, name: 'classify', started_at: prompt.timestamp_prompt_built, duration_ms: policy.latency_ms,
    detail: {
      model: policy.model_used,
      fallback_triggered: policy.fallback_triggered,
      prompt_tokens: policy.prompt_tokens,
      completion_tokens: policy.completion_tokens,
      cost_usd: policy.cost_usd,
      validation_success: policy.validation_success,
    } },
  { step: 5, name: 'policy',
    detail: {
      decision: policy.decision,
      destination: policy.destination,
      escalation_reason: policy.escalation_reason,
      escalation_priority: policy.escalation_priority,
      policies_passed: policy.policies_passed,
      policies_failed: policy.policies_failed,
    } },
  { step: 6, name: 'store_results', finished_at: finishedAt.toISOString() },
];

// success = the run finished and a decision was saved.
// error_* = a step had a problem the run handled, e.g. a slip that failed check 0.
const validationFailed = policy.validation_success === false;

return [{
  json: {
    trace_id: `trace_${meta.request_id}`,
    request_id: meta.request_id,
    success: true,
    total_latency_ms: finishedAt.getTime() - Date.parse(meta.timestamp_started),
    total_cost_usd: policy.cost_usd,
    steps: steps,
    error_occured: validationFailed,
    error_step: validationFailed ? 4 : null,
    error_message: validationFailed ? 'LLM output failed validation' : null,
    error_details: validationFailed ? { validation_errors: policy.validation_errors } : null,
  }
}];

