// === BUILD SLACK ALERT ===
// Runs only for escalated emails. Builds the message a reviewer sees in Slack.

const meta = $('Generate Request Metadata').item.json;
const policy = $('Policy Engine').item.json;
const c = policy.classification ?? {};

const REASON_TEXT = {
  critical_risk_flag: 'A serious risk flag was found',
  low_confidence: 'The model was not confident enough',
  budget_exceeded: 'The call cost too much or took too long',
  invalid_llm_output: 'The model answered in the wrong format',
  llm_unavailable: 'No model answered',
};

const flags = (c.risk_flags ?? []).length ? c.risk_flags.join(', ') : 'none';
const reason = policy.escalation_reason;
const summary = policy.validation_success === false
  ? `The model's answer could not be used: ${(policy.validation_errors ?? []).join('; ')}`
  : (c.summary || 'no summary');

const payload = {
  text: `Escalated: ${c.intent} (${policy.escalation_priority})`,
  blocks: [
    { type: 'header', text: { type: 'plain_text', text: `Escalated email: ${policy.escalation_priority} priority` } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: `*Why:*\n${REASON_TEXT[reason] ?? reason}` },
      { type: 'mrkdwn', text: `*Category:*\n${c.intent} (confidence ${c.confidence})` },
      { type: 'mrkdwn', text: `*Risk flags:*\n${flags}` },
      { type: 'mrkdwn', text: `*From:*\n${meta.from}` },
    ] },
    { type: 'section', text: { type: 'mrkdwn', text: `*Subject:* ${meta.subject}\n*Summary:* ${summary}` } },
    { type: 'context', elements: [ { type: 'mrkdwn',
      text: `${meta.request_id} · queue ${policy.destination} · model ${policy.model_used} · $${policy.cost_usd} · ${policy.latency_ms} ms` } ] },
  ],
};

return [{ json: { payload: payload } }];
